ALTER TABLE deployment_unit_environment DROP CHECK deployment_unit_environment_chk_1, ADD CONSTRAINT deployment_unit_environment_allowed CHECK (environment IN ('TEST','SIMULATION','PRODUCT','UNIDENTIFIED'));
ALTER TABLE catalog_observation DROP CHECK catalog_observation_chk_1, ADD CONSTRAINT catalog_observation_allowed CHECK (((record_kind IN ('APPLICATION','COMPONENT')) AND unit_id IS NOT NULL AND unit_environment_id IS NULL AND instance_id IS NULL) OR (record_kind IN ('ENVIRONMENT','UNRESOLVED_DEPLOYMENT') AND unit_id IS NULL AND unit_environment_id IS NOT NULL AND instance_id IS NULL) OR (record_kind='DEPLOYMENT' AND unit_id IS NULL AND unit_environment_id IS NULL AND instance_id IS NOT NULL));
CREATE TABLE IF NOT EXISTS catalog_component_counter (technology VARCHAR(100) PRIMARY KEY, next_number BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
